import sys
sys.path.insert(0,'/workspace')
src=open('compose.py').read()
NS={}
exec(compile(src.split("order = list(range(NPAT))")[0],'c','exec'), NS)
CH=NS['CH']; PROG=NS['PROG']; patterns=NS['patterns']
NAMES=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
def pc(m): return m%12
for pi,pat in enumerate(patterns):
    prog=PROG[pi]
    for b in range(4):
        chord=CH[prog[b]]
        tones=set((chord['root']+i)%12 for i in (0,7,12)) | {(chord['root']+chord['third'])%12}
        # collect notes sounding in this bar from lead(0), harm(1), arp(6), pad(2-5), bass(7)
        bad=[]
        for r in range(b*16, b*16+16):
            for c in (0,1,6):
                cell=pat[r][c]
                if cell is None or cell.inst is None or cell.note is None: continue
                if cell.note=='off': continue
                # midi from note number: note = midi-11
                midi=cell.note+11
                p=pc(midi)
                if p not in tones:
                    # distance to nearest chord tone
                    dist=min(min(abs(p-t),12-abs(p-t)) for t in tones)
                    if dist==1: bad.append((r,c,NAMES[p],cell.inst))
        if bad: print(f'P{pi} bar{b} {prog[b]}: clashes', bad)
print('clash check done')
# also print the pitch classes used per bar for the lead
for pi,pat in enumerate(patterns):
    s=[]
    for b in range(4):
        ps=set()
        for r in range(b*16,b*16+16):
            cell=pat[r][0]
            if cell and cell.note and cell.note!='off': ps.add(NAMES[(cell.note+11)%12])
        s.append('/'.join(sorted(ps)))
    print(f'P{pi} lead notes per bar:', s)
EOF"}

